#pragma once

// A language definition for the colorizer. The definitions are generated by script/PortUpstream.py.

#include "TextEdit.h"

#include <string>
#include <unordered_set>

namespace ipte {
using Iterator = const uint64_t *;

struct Language {
    using Tokenizer = Iterator (*)(Iterator start, Iterator end);
    using LevelTokenizer = Iterator (*)(Iterator start, Iterator end, size_t &level);
    using ColoringTokenizer = Iterator (*)(Iterator start, Iterator end, Color &color);

    std::string Name;
    bool CaseSensitive{true};
    uint64_t Preprocess{0};
    std::string SingleLineComment, SingleLineCommentAlt;
    std::string CommentStart, CommentEnd;
    LevelTokenizer CommentLevelStart{nullptr}, CommentLevelEnd{nullptr};
    bool HasSingleQuotedStrings{false}, HasDoubleQuotedStrings{false};
    std::string OtherStringStart, OtherStringEnd, OtherStringAltStart, OtherStringAltEnd;
    uint64_t StringEscape{0};
    LevelTokenizer StringLevelStart{nullptr}, StringLevelEnd{nullptr};
    bool IndentationForBlocks{false};
    std::unordered_set<std::string> Keywords, Declarations, Identifiers;
    bool (*IsPunctuation)(uint64_t){nullptr};
    Tokenizer GetIdentifier{nullptr}, GetNumber{nullptr};
    ColoringTokenizer CustomTokenizer{nullptr};
};

const Language *C();
const Language *Cpp();
const Language *Cs();
const Language *AngelScript();
const Language *Lua();
const Language *Python();
const Language *Glsl();
const Language *Hlsl();
const Language *Json();
const Language *Markdown();
const Language *Sql();
} // namespace ipte
